def antipode_test(vectors: list[list[float]], *, threshold: float = 0.0) -> tuple[int, list[int]]:
    if not vectors:
        return 0, []
    c = centroid(vectors)
    sims = [cosine_similarity(v, c) for v in vectors]
    if threshold == 0.0:
        effective = sum(sims) / len(sims)
    else:
        effective = threshold
    kept = [i for i, s in enumerate(sims) if s >= effective]
    return len(kept), kept
